-- ============================================================================
-- A reset does not take the mail templates with it (2026-11-20).
--
-- Read on sandbox the morning after its nightly rebuild: email_templates held
-- NO rows. sandbox_reset_wipe empties every table it is not told to keep, the
-- templates were not on its list, and they are seeded by migrations — which
-- never run a second time. So since the first rebuild every mail sandbox sent
-- was the built-in English fallback, and none of the template work (the mails
-- in the customer's language, the Swedish seeds) was ever seen by a tester.
-- reset_site_data, the one a real instance can run, had the same hole.
--
-- The lesson is the squash's (2026-06-08): platform configuration that only
-- a migration seeds is lost by anything that empties its table.
--
--   seed_platform_email_templates()  every template the platform ships, en and
--                                    sv, inserted where (name, locale) is
--                                    missing. One place, callable again.
--   sandbox_reset_wipe               calls it after the wipe: a rebuilt sandbox
--                                    has the platform's mails, and a tester's
--                                    edits do not survive the night.
--   reset_site_data                  keeps email_templates: a business's own
--                                    wording is configuration, like its
--                                    settings.
--
-- Run once here, so an instance that already lost its templates has them back.
-- A new template migration adds its rows to seed_platform_email_templates too
-- (a guard compares the two).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.seed_platform_email_templates()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $seed$
DECLARE
  v_added integer;
BEGIN
  -- Only where (name, locale) is missing: a version an instance wrote itself
  -- is never replaced. The locale is stated, so no trigger stamps the site's.
  INSERT INTO public.email_templates (name, locale, subject, html, text, category, variables, active)
  SELECT t.name, t.locale, t.subject, t.html, t.text, t.category, t.variables, true
    FROM (VALUES
    ('application_received', 'en', $s$We received your application — {{job_title}}$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">Thank you for your application</h2><p>Hi{{#candidate_name}} {{candidate_name}}{{/candidate_name}},</p><p>We have received your application for <strong>{{job_title}}</strong>. We read every application ourselves and will get back to you as soon as we can.</p><p>Kind regards,<br>{{site_name}}</p>$h$, NULL, 'transactional', $v$["candidate_name", "job_title", "site_name"]$v$::jsonb),
    ('application_received', 'sv', $s$Vi har tagit emot din ansökan — {{job_title}}$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">Tack för din ansökan</h2><p>Hej{{#candidate_name}} {{candidate_name}}{{/candidate_name}}!</p><p>Vi har tagit emot din ansökan till tjänsten <strong>{{job_title}}</strong>. Vi läser varje ansökan själva och hör av oss så snart vi kan.</p><p>Vänliga hälsningar<br>{{site_name}}</p>$h$, NULL, 'transactional', $v$["candidate_name", "job_title", "site_name"]$v$::jsonb),
    ('booking_confirmation', 'en', $s$Booking confirmation — {{date}}$s$, $h$<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Booking confirmation</title></head><body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;"><h1 style="font-size: 22px; margin: 0 0 16px;">Booking confirmation</h1><p>Hello {{customer_name}},</p><p>Thank you for your booking. Here are the details:</p><div style="background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; margin: 20px 0;"><p style="margin:4px 0;"><strong>Service:</strong> {{service_name}}</p><p style="margin:4px 0;"><strong>Date:</strong> {{date}}</p><p style="margin:4px 0;"><strong>Time:</strong> {{start_time}}–{{end_time}}</p></div>{{#notes}}<div style="background:#f3f4f6;border-radius:8px;padding:12px 16px;margin:16px 0;"><p style="margin:0;"><strong>Your note:</strong> {{notes}}</p></div>{{/notes}}<p>If anything changes, just reply to this email.</p><p style="color:#6b7280; font-size: 13px; margin-top: 28px;">{{site_name}}</p></body></html>$h$, $t$Hello {{customer_name}}, your booking of {{service_name}} on {{date}} at {{start_time}}–{{end_time}} is received. {{site_name}}$t$, 'transactional', $v$["customer_name", "service_name", "date", "start_time", "end_time", "site_name", "notes"]$v$::jsonb),
    ('booking_confirmation', 'sv', $s$Bokningsbekräftelse — {{date}}$s$, $h$<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Bokningsbekräftelse</title></head><body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px;"><h1 style="font-size: 22px; margin: 0 0 16px;">Bokningsbekräftelse</h1><p>Hej {{customer_name}},</p><p>Tack för din bokning. Här är uppgifterna:</p><div style="background: #f9fafb; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; margin: 20px 0;"><p style="margin:4px 0;"><strong>Tjänst:</strong> {{service_name}}</p><p style="margin:4px 0;"><strong>Datum:</strong> {{date}}</p><p style="margin:4px 0;"><strong>Tid:</strong> {{start_time}}–{{end_time}}</p></div>{{#notes}}<div style="background:#f3f4f6;border-radius:8px;padding:12px 16px;margin:16px 0;"><p style="margin:0;"><strong>Din anteckning:</strong> {{notes}}</p></div>{{/notes}}<p>Om något ändras, svara bara på det här mejlet.</p><p style="color:#6b7280; font-size: 13px; margin-top: 28px;">{{site_name}}</p></body></html>$h$, NULL, 'transactional', $v$["customer_name", "service_name", "date", "start_time", "end_time", "site_name", "notes"]$v$::jsonb),
    ('booking_reminder', 'en', $s$Reminder: your booking on {{date}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Reminder about your booking</h1><p style="margin:0 0 12px">Hello{{#customer_name}} {{customer_name}}{{/customer_name}},</p><p style="margin:0 0 12px;color:#374151">This is a reminder about your upcoming booking:</p><div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px 20px;margin:16px 0">{{#service_name}}<p style="margin:4px 0"><strong>Service:</strong> {{service_name}}</p>{{/service_name}}<p style="margin:4px 0"><strong>Date:</strong> {{date}}</p><p style="margin:4px 0"><strong>Time:</strong> {{start_time}}–{{end_time}}</p>{{#duration_minutes}}<p style="margin:4px 0"><strong>Duration:</strong> {{duration_minutes}} minutes</p>{{/duration_minutes}}{{#meeting_url}}<p style="margin:4px 0"><strong>Join the meeting:</strong> <a href="{{meeting_url}}">{{meeting_url}}</a></p>{{/meeting_url}}</div><p style="margin:0;color:#6b7280;font-size:14px">If you need to change or cancel your booking, please contact us as soon as possible.</p><p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["customer_name", "service_name", "date", "start_time", "end_time", "duration_minutes", "meeting_url", "site_name"]$v$::jsonb),
    ('booking_reminder', 'sv', $s$Påminnelse: din bokning {{date}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Påminnelse om din bokning</h1><p style="margin:0 0 12px">Hej{{#customer_name}} {{customer_name}}{{/customer_name}}!</p><p style="margin:0 0 12px;color:#374151">Här kommer en påminnelse om din bokning:</p><div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px 20px;margin:16px 0">{{#service_name}}<p style="margin:4px 0"><strong>Tjänst:</strong> {{service_name}}</p>{{/service_name}}<p style="margin:4px 0"><strong>Datum:</strong> {{date}}</p><p style="margin:4px 0"><strong>Tid:</strong> {{start_time}}–{{end_time}}</p>{{#duration_minutes}}<p style="margin:4px 0"><strong>Längd:</strong> {{duration_minutes}} minuter</p>{{/duration_minutes}}{{#meeting_url}}<p style="margin:4px 0"><strong>Länk till mötet:</strong> <a href="{{meeting_url}}">{{meeting_url}}</a></p>{{/meeting_url}}</div><p style="margin:0;color:#6b7280;font-size:14px">Behöver du ändra eller avboka? Hör av dig till oss så snart som möjligt.</p><p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["customer_name", "service_name", "date", "start_time", "end_time", "duration_minutes", "meeting_url", "site_name"]$v$::jsonb),
    ('calendar_reminder', 'en', $s$Reminder: {{title}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Reminder about your upcoming event</h1><p style="margin:0 0 12px">Hello{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">This is a reminder about an event in your calendar:</p><div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px 20px;margin:16px 0"><p style="margin:4px 0"><strong>{{title}}</strong></p><p style="margin:4px 0"><strong>Date:</strong> {{date}}</p><p style="margin:4px 0"><strong>Time:</strong> {{start_time}}{{#end_time}}–{{end_time}}{{/end_time}}</p>{{#location}}<p style="margin:4px 0"><strong>Location:</strong> {{location}}</p>{{/location}}</div><p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["name", "title", "date", "start_time", "end_time", "location", "site_name"]$v$::jsonb),
    ('calendar_reminder', 'sv', $s$Påminnelse: {{title}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Påminnelse inför {{title}}</h1><p style="margin:0 0 12px">Hej{{#name}} {{name}}{{/name}}!</p><p style="margin:0 0 12px;color:#374151">Här kommer en påminnelse om något som snart står i din kalender:</p><div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:16px 20px;margin:16px 0"><p style="margin:4px 0"><strong>{{title}}</strong></p><p style="margin:4px 0"><strong>Datum:</strong> {{date}}</p><p style="margin:4px 0"><strong>Tid:</strong> {{start_time}}{{#end_time}}–{{end_time}}{{/end_time}}</p>{{#location}}<p style="margin:4px 0"><strong>Plats:</strong> {{location}}</p>{{/location}}</div><p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["name", "title", "date", "start_time", "end_time", "location", "site_name"]$v$::jsonb),
    ('contract_email', 'en', $s$Agreement {{contract_number}} from {{site_name}} — ready to sign$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">{{contract_title}}</h2><p>Please review and sign the agreement below.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:12px 16px;margin:16px 0;font-size:14px"><div><span style="color:#6b7280">Agreement</span> &nbsp; <strong>{{contract_number}}</strong></div></div><p style="margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;padding:12px 24px;background-color:#111;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600">Review &amp; sign</a></p><p style="font-size:12px;color:#6b7280;word-break:break-all">Or open this link:<br/>{{cta_url}}</p>$h$, NULL, 'sales', $v$["contract_title", "contract_number", "site_name", "cta_url", "custom_block"]$v$::jsonb),
    ('contract_email', 'sv', $s$Avtal {{contract_number}} från {{site_name}} — klart att signera$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">{{contract_title}}</h2><p>Läs igenom och signera avtalet nedan.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:12px 16px;margin:16px 0;font-size:14px"><div><span style="color:#6b7280">Avtal</span> &nbsp; <strong>{{contract_number}}</strong></div></div><p style="margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;padding:12px 24px;background-color:#111;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600">Läs och signera</a></p><p style="font-size:12px;color:#6b7280;word-break:break-all">Eller öppna länken:<br/>{{cta_url}}</p>$h$, NULL, 'sales', $v$["contract_title", "contract_number", "site_name", "cta_url", "custom_block"]$v$::jsonb),
    ('contract_reminder', 'en', $s$Reminder: sign {{contract_number}} from {{site_name}}$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">{{contract_title}}</h2><p>A reminder to review and sign the agreement below.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:12px 16px;margin:16px 0;font-size:14px"><div><span style="color:#6b7280">Agreement</span> &nbsp; <strong>{{contract_number}}</strong></div></div><p style="margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;padding:12px 24px;background-color:#111;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600">Review &amp; sign</a></p><p style="font-size:12px;color:#6b7280;word-break:break-all">Or open this link:<br/>{{cta_url}}</p>$h$, NULL, 'sales', $v$["contract_title", "contract_number", "site_name", "cta_url", "custom_block"]$v$::jsonb),
    ('contract_reminder', 'sv', $s$Påminnelse: signera {{contract_number}} från {{site_name}}$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">{{contract_title}}</h2><p>En påminnelse om att läsa igenom och signera avtalet nedan.</p>{{custom_block}}<div style="background:#f9fafb;border:1px solid #e6e8ec;border-radius:8px;padding:12px 16px;margin:16px 0;font-size:14px"><div><span style="color:#6b7280">Avtal</span> &nbsp; <strong>{{contract_number}}</strong></div></div><p style="margin:24px 0"><a href="{{cta_url}}" style="display:inline-block;padding:12px 24px;background-color:#111;color:#ffffff;text-decoration:none;border-radius:6px;font-weight:600">Läs och signera</a></p><p style="font-size:12px;color:#6b7280;word-break:break-all">Eller öppna länken:<br/>{{cta_url}}</p>$h$, NULL, 'sales', $v$["contract_title", "contract_number", "site_name", "cta_url", "custom_block"]$v$::jsonb),
    ('dunning-step-1', 'en', $s$Your payment for {{product_name}} did not go through$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">We could not take your payment</h1><p style="margin:0 0 12px">Hi{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">The payment of {{amount}} for {{product_name}} did not go through. Please check your card or payment details — we will try again automatically.</p><p style="margin:0;color:#6b7280;font-size:13px">If you have already updated your details, you can ignore this message.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-1', 'sv', $s$Din betalning för {{product_name}} gick inte igenom$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Vi kunde inte dra betalningen</h1><p style="margin:0 0 12px">Hej{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">Betalningen på {{amount}} för {{product_name}} gick inte igenom. Kontrollera ditt kort eller dina betaluppgifter — vi försöker igen automatiskt.</p><p style="margin:0;color:#6b7280;font-size:13px">Har du redan uppdaterat dina uppgifter kan du bortse från det här meddelandet.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-2', 'en', $s$Reminder: payment for {{product_name}} is still outstanding$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Your payment is still outstanding</h1><p style="margin:0 0 12px">Hi{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">We still have not been able to collect {{amount}} for {{product_name}} (attempt {{attempt_count}}). Please update your payment details to keep your subscription active.</p><p style="margin:0;color:#6b7280;font-size:13px">If you have already paid, you can ignore this message.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-2', 'sv', $s$Påminnelse: betalningen för {{product_name}} är fortfarande obetald$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Betalningen är fortfarande obetald</h1><p style="margin:0 0 12px">Hej{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">Vi har ännu inte kunnat dra {{amount}} för {{product_name}} (försök {{attempt_count}}). Uppdatera dina betaluppgifter så att prenumerationen fortsätter.</p><p style="margin:0;color:#6b7280;font-size:13px">Har du redan betalat kan du bortse från det här meddelandet.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-3', 'en', $s$Urgent: {{product_name}} will be paused soon$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Action needed</h1><p style="margin:0 0 12px">Hi{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">The payment of {{amount}} for {{product_name}} is still outstanding. Please update your payment details as soon as possible to avoid interruption.</p><p style="margin:0;color:#6b7280;font-size:13px">Questions? Just reply to this e-mail.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-3', 'sv', $s$Brådskande: {{product_name}} pausas snart$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Åtgärd krävs</h1><p style="margin:0 0 12px">Hej{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">Betalningen på {{amount}} för {{product_name}} är fortfarande obetald. Uppdatera dina betaluppgifter så snart som möjligt för att undvika avbrott.</p><p style="margin:0;color:#6b7280;font-size:13px">Frågor? Svara bara på det här mejlet.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
    ('dunning-step-4', 'en', $s$Final notice: payment for {{product_name}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">Final notice</h1><p style="margin:0 0 12px">Hi{{#name}} {{name}}{{/name}},</p><p style="margin:0 0 12px;color:#374151">This is our final reminder about {{amount}} for {{product_name}}. If we cannot collect the payment, the subscription will be cancelled.</p><p style="margin:0;color:#6b7280;font-size:13px">Questions? Just reply to this e-mail.</p></div></body></html>$h$, NULL, 'billing', $v$["name", "product_name", "amount", "attempt_count", "failure_reason"]$v$::jsonb),
