    ('return_confirmation', 'en', $s$Return approved — {{rma_number}}$s$, $h$<h2 style="margin:0 0 12px;font-size:20px">Your return has been approved</h2><p>Hi{{#customer_name}} {{customer_name}}{{/customer_name}},</p><p>We've approved your return request <strong>{{rma_number}}</strong>.</p>{{#label_url}}<p><strong>Return label:</strong> <a href="{{label_url}}">Download label (PDF)</a></p>{{/label_url}}{{#no_label}}<p><em>A return label will be sent separately.</em></p>{{/no_label}}{{#tracking}}<p><strong>Tracking:</strong> {{tracking}}</p>{{/tracking}}<h3 style="margin:20px 0 8px;font-size:16px">Return instructions</h3>{{#custom_instructions}}<p>{{custom_instructions}}</p>{{/custom_instructions}}{{#standard_instructions}}<p>Please pack the item(s) securely, in the original packaging when possible. Attach the return label to the outside of the package and drop it off at your nearest carrier location.</p>{{/standard_instructions}}<p style="color:#666;font-size:12px;margin-top:32px">Please quote the RMA number {{rma_number}} whenever you contact us about this return.</p>$h$, NULL, 'commerce', $v$["customer_name", "rma_number", "label_url", "no_label", "tracking", "custom_instructions", "standard_instructions"]$v$::jsonb),
