    ('webinar_reminder', 'en', $s${{#is_confirm}}You're registered: {{title}}{{/is_confirm}}{{#is_t24}}Tomorrow: {{title}}{{/is_t24}}{{#is_t1}}Starting soon: {{title}}{{/is_t1}}{{#is_attended}}Thanks for joining {{title}}{{/is_attended}}{{#is_missed}}We missed you at {{title}}{{/is_missed}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">{{#is_confirm}}You're registered!{{/is_confirm}}{{#is_t24}}Starting in 24 hours{{/is_t24}}{{#is_t1}}Starting within the hour{{/is_t1}}{{#is_attended}}Thanks for joining!{{/is_attended}}{{#is_missed}}We missed you{{/is_missed}}</h1><p style="margin:0 0 16px;color:#4b5563">Hi{{#name}} {{name}}{{/name}},</p>{{#is_confirm}}<p style="margin:0 0 8px;color:#4b5563">Your spot for <strong>{{title}}</strong> is confirmed.</p><p style="margin:0;color:#4b5563">{{when}}</p>{{/is_confirm}}{{#is_t24}}<p style="margin:0 0 8px;color:#4b5563"><strong>{{title}}</strong> starts tomorrow.</p><p style="margin:0;color:#4b5563">{{when}}</p>{{/is_t24}}{{#is_t1}}<p style="margin:0 0 8px;color:#4b5563"><strong>{{title}}</strong> is about to begin.</p>{{/is_t1}}{{#is_attended}}<p style="margin:0;color:#4b5563">Great to have you at <strong>{{title}}</strong>.</p>{{/is_attended}}{{#is_missed}}<p style="margin:0;color:#4b5563">Sorry we didn't see you at <strong>{{title}}</strong>.</p>{{/is_missed}}{{#join_url}}<p style="margin:16px 0"><a href="{{join_url}}" style="display:inline-block;background:#111;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">Join the webinar</a></p>{{/join_url}}{{#recording_url}}<p style="margin:16px 0"><a href="{{recording_url}}" style="display:inline-block;background:#111;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">Watch the recording</a></p>{{/recording_url}}<p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["name", "title", "when", "join_url", "recording_url", "site_name", "is_confirm", "is_t24", "is_t1", "is_attended", "is_missed"]$v$::jsonb),
    ('webinar_reminder', 'sv', $s${{#is_confirm}}Du är anmäld: {{title}}{{/is_confirm}}{{#is_t24}}I morgon: {{title}}{{/is_t24}}{{#is_t1}}Snart börjar det: {{title}}{{/is_t1}}{{#is_attended}}Tack för att du var med på {{title}}{{/is_attended}}{{#is_missed}}Vi saknade dig på {{title}}{{/is_missed}}$s$, $h$<!doctype html><html><body style="font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:#f6f7f9;margin:0;padding:24px;color:#111"><div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;border:1px solid #e6e8ec"><h1 style="margin:0 0 12px;font-size:20px">{{#is_confirm}}Du är anmäld!{{/is_confirm}}{{#is_t24}}I morgon är det dags{{/is_t24}}{{#is_t1}}Vi börjar inom en timme{{/is_t1}}{{#is_attended}}Tack för att du var med!{{/is_attended}}{{#is_missed}}Vi saknade dig{{/is_missed}}</h1><p style="margin:0 0 16px;color:#4b5563">Hej{{#name}} {{name}}{{/name}}!</p>{{#is_confirm}}<p style="margin:0 0 8px;color:#4b5563">Din plats på <strong>{{title}}</strong> är bekräftad.</p><p style="margin:0;color:#4b5563">{{when}}</p>{{/is_confirm}}{{#is_t24}}<p style="margin:0 0 8px;color:#4b5563"><strong>{{title}}</strong> börjar i morgon.</p><p style="margin:0;color:#4b5563">{{when}}</p>{{/is_t24}}{{#is_t1}}<p style="margin:0 0 8px;color:#4b5563"><strong>{{title}}</strong> börjar alldeles strax.</p>{{/is_t1}}{{#is_attended}}<p style="margin:0;color:#4b5563">Roligt att du var med på <strong>{{title}}</strong>.</p>{{/is_attended}}{{#is_missed}}<p style="margin:0;color:#4b5563">Tråkigt att vi inte såg dig på <strong>{{title}}</strong>.</p>{{/is_missed}}{{#join_url}}<p style="margin:16px 0"><a href="{{join_url}}" style="display:inline-block;background:#111;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">Gå med i webbinariet</a></p>{{/join_url}}{{#recording_url}}<p style="margin:16px 0"><a href="{{recording_url}}" style="display:inline-block;background:#111;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">Se inspelningen</a></p>{{/recording_url}}<p style="margin:24px 0 0;color:#9ca3af;font-size:12px">{{site_name}}</p></div></body></html>$h$, NULL, 'transactional', $v$["name", "title", "when", "join_url", "recording_url", "site_name", "is_confirm", "is_t24", "is_t1", "is_attended", "is_missed"]$v$::jsonb),
    ('welcome', 'en', $s$Welcome to {{company_name}}!$s$, $h$<div style="font-family:system-ui,sans-serif;max-width:560px;margin:0 auto;padding:24px"><h2>Welcome, {{first_name}}!</h2><p>Thanks for joining {{company_name}}. We're glad to have you.</p><p>If you have any questions, just reply to this email.</p></div>$h$, $t$Welcome, {{first_name}}! Thanks for joining {{company_name}}.$t$, 'onboarding', $v$["first_name", "company_name"]$v$::jsonb)
    ) AS t(name, locale, subject, html, text, category, variables)
   WHERE NOT EXISTS (SELECT 1 FROM public.email_templates e WHERE e.name = t.name AND e.locale = t.locale);
  GET DIAGNOSTICS v_added = ROW_COUNT;
  RETURN v_added;
END;
$seed$;

REVOKE ALL ON FUNCTION public.seed_platform_email_templates() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seed_platform_email_templates() TO service_role;

CREATE OR REPLACE FUNCTION public.sandbox_reset_wipe(p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  KEEP text[] := ARRAY[
    -- identity, config, agent surface
    'agent_skills','agent_automations','agent_trust_policies',
    'site_settings','user_roles','profiles','api_keys',
    -- role/nav matrix (empty here = every non-admin sees an empty product)
    'role_module_access','role_module_access_defaults',
    -- accounting reference
    'chart_of_accounts','account_roles','accounting_templates','locale_packs',
    'account_tax_boxes','journals','currencies',
    -- operational reference
    'payroll_country_profiles','expense_rate_tables','postal_code_rules',
    'pipeline_stages','business_hours',
    'uoms','uom_categories'
  ];
  _demo jsonb;
  _legacy jsonb;
  _admin_email text;
  _tables text[];
  _users_deleted int := 0;
  _skill_count int;
  _settings_count int;
BEGIN
  -- FIRST. Before the confirm token, before the role check, before anything
  -- that could be satisfied by an operator who knows the password. On a testbed
  -- there is no correct set of arguments to this function.
  PERFORM public.assert_not_testbed('sandbox_reset_wipe');

  IF p_confirm IS DISTINCT FROM 'WIPE-SANDBOX' THEN
    RAISE EXCEPTION 'sandbox_reset_wipe requires p_confirm = ''WIPE-SANDBOX''';
  END IF;

  SELECT value INTO _demo   FROM public.site_settings WHERE key = 'demo_mode';
  SELECT value INTO _legacy FROM public.site_settings WHERE key = 'sandbox_mode';
  IF NOT (
       _demo = 'true'::jsonb OR (_demo ->> 'enabled') = 'true'
    OR _legacy = 'true'::jsonb OR (_legacy ->> 'enabled') = 'true'
  ) THEN
    RAISE EXCEPTION 'sandbox_reset_wipe refused: this instance is not a demo (site_settings.demo_mode is not enabled)';
  END IF;

  IF NOT (auth.role() = 'service_role' OR has_role(auth.uid(), 'admin'::app_role)) THEN
    RAISE EXCEPTION 'Only service_role or an admin can reset the sandbox';
  END IF;

  SELECT COALESCE(
    NULLIF((SELECT value #>> '{}' FROM public.site_settings WHERE key = 'sandbox_admin_email'), ''),
    'demo@flowwink.com'
  ) INTO _admin_email;

  SELECT array_agg(tablename ORDER BY tablename) INTO _tables
    FROM pg_tables
   WHERE schemaname = 'public'
     AND NOT (tablename = ANY(KEEP));

  IF _tables IS NOT NULL AND array_length(_tables, 1) > 0 THEN
    EXECUTE 'TRUNCATE TABLE '
      || (SELECT string_agg(format('public.%I', t), ', ') FROM unnest(_tables) AS t)
      || ' RESTART IDENTITY CASCADE';
  END IF;

  DELETE FROM auth.users WHERE lower(email) IS DISTINCT FROM lower(_admin_email);
  GET DIAGNOSTICS _users_deleted = ROW_COUNT;
  UPDATE auth.users
     SET encrypted_password = extensions.crypt('demo1234', extensions.gen_salt('bf')),
         email_confirmed_at = COALESCE(email_confirmed_at, now())
   WHERE lower(email) = lower(_admin_email);

  SELECT count(*) INTO _skill_count FROM public.agent_skills;
  SELECT count(*) INTO _settings_count FROM public.site_settings;
  IF _skill_count = 0 OR _settings_count = 0 THEN
    RAISE EXCEPTION 'sandbox_reset_wipe rollback: a keep-table was emptied (agent_skills=%, site_settings=%)',
      _skill_count, _settings_count;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE lower(email) = lower(_admin_email)) THEN
    RAISE EXCEPTION 'sandbox_reset_wipe rollback: sandbox admin % missing after auth normalize', _admin_email;
  END IF;

  -- The platform's mail templates are seeded by migrations, which never run
  -- again: the wipe emptied them and nothing put them back.
  PERFORM public.seed_platform_email_templates();

  RETURN jsonb_build_object(
    'tables_wiped', COALESCE(array_length(_tables, 1), 0),
    'users_deleted', _users_deleted,
    'admin_email', _admin_email,
    'skills_kept', _skill_count
  );
END $fn$;

CREATE OR REPLACE FUNCTION public.reset_site_data(p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  KEEP text[] := ARRAY[
    -- identity & access (admin user survives)
    'profiles','user_roles','role_module_access','role_module_access_defaults',
    -- instance config & credentials (Supabase/gateway connections)
    'site_settings','api_keys',
    -- seeded platform layers
    'agent_skills','agent_skill_packs','agent_trust_policies',
    'chart_of_accounts','account_roles','accounting_templates','locale_packs','currencies',
    -- migration bookkeeping
    -- the business's mail templates: its own wording, and the platform's seeds
    'email_templates',
    'schema_migrations','supabase_migrations'
  ];
  _tables text[];
  _skills int;
  _settings int;
  _roles int;
  _profiles int;
BEGIN
  PERFORM set_config('app.archive_override', 'on', true);
  PERFORM public.assert_not_testbed('reset_site_data');

  IF p_confirm IS DISTINCT FROM 'RESET-SITE' THEN
    RAISE EXCEPTION 'reset_site_data requires p_confirm = ''RESET-SITE''';
  END IF;

  IF NOT (auth.role() = 'service_role' OR has_role(auth.uid(), 'admin'::app_role)) THEN
    RAISE EXCEPTION 'Only an admin can reset the site';
  END IF;

  SELECT array_agg(tablename ORDER BY tablename) INTO _tables
    FROM pg_tables
   WHERE schemaname = 'public'
     AND NOT (tablename = ANY(KEEP));

  IF _tables IS NOT NULL AND array_length(_tables, 1) > 0 THEN
    EXECUTE 'TRUNCATE TABLE '
      || (SELECT string_agg(format('public.%I', t), ', ') FROM unnest(_tables) AS t)
      || ' RESTART IDENTITY CASCADE';
  END IF;

  SELECT count(*) INTO _skills FROM public.agent_skills;
  SELECT count(*) INTO _settings FROM public.site_settings;
  SELECT count(*) INTO _roles FROM public.user_roles;
  SELECT count(*) INTO _profiles FROM public.profiles;

  IF _skills = 0 OR _settings = 0 OR _roles = 0 OR _profiles = 0 THEN
    RAISE EXCEPTION 'reset_site_data rollback: a keep-table was emptied (skills=%, settings=%, user_roles=%, profiles=%)',
      _skills, _settings, _roles, _profiles;
  END IF;

  RETURN jsonb_build_object(
    'tables_wiped', COALESCE(array_length(_tables, 1), 0),
    'tables_kept', array_length(KEEP, 1),
    'skills_kept', _skills,
    'admins_kept', _roles
  );
END $fn$;

-- As before: the wipe is the platform's own, the site reset an admin's.
REVOKE ALL ON FUNCTION public.sandbox_reset_wipe(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.sandbox_reset_wipe(text) TO service_role;
REVOKE ALL ON FUNCTION public.reset_site_data(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reset_site_data(text) TO authenticated, service_role;

SELECT public.seed_platform_email_templates();

-- ── Proof: reads only ────────────────────────────────────────────────────────
DO $$
DECLARE
  kind text;
  v jsonb;
BEGIN
  FOREACH kind IN ARRAY ARRAY['booking_confirmation','quote_email','contract_email','invoice_email','invoice_reminder','order_confirmation','order_receipt','booking_reminder'] LOOP
    v := public.resolve_email_template(kind, 'sv');
    IF v IS NULL OR (v->>'ok') IS DISTINCT FROM 'true' THEN
      RAISE EXCEPTION 'after the seed there is still no % template: %', kind, v;
    END IF;
  END LOOP;
  IF public.seed_platform_email_templates() <> 0 THEN
    RAISE EXCEPTION 'the seed is not idempotent';
  END IF;
END $$;
